anchor":"serve"}}],"phases":[{"id":"heat","kind":"heating","estimatedMinutes":780,"durationStepId":"start","upperMinutes":1080},{"id":"rest","kind":"passive","estimatedMinutes":360,"durationStepId":"rest","after":"heat"}],"suppressedStepIds":[],"review":{"addedSteps":[],"taskOrder":["season","prep","preheat","start","check","wrap","finish","rest","serve"],"hiddenStepIds":[],"overrides":{"prep":{"title":"My first step","instructions":"My first instructions","durationMinutes":90,"equipment":"Oven","targetTempF":195},"season":{"title":"My second step","instructions":"My second instructions","durationMinutes":45,"equipment":"Oven","targetTempF":195}}}}}$editedRecipe$::jsonb,'{id}',to_jsonb(id::text)) $$;
create function pg_temp.assert_recipe(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_recipe((public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000020',0,'b1400000-0000-4000-8000-000000000020','save',pg_temp.edited_recipe('a1400000-0000-4000-8000-000000000020') #- '{recipe,review}')->>'revision')::int=1,'create original');
select pg_temp.assert_recipe(public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000020',1,'b1400000-0000-4000-8000-000000000021','save',pg_temp.edited_recipe('a1400000-0000-4000-8000-000000000020'))->'document'=pg_temp.edited_recipe('a1400000-0000-4000-8000-000000000020'),'all edited metadata acknowledged');
select pg_temp.assert_recipe(public.mutate_personal_recipe(auth.uid(),'a1400000-0000-4000-8000-000000000021',0,'b1400000-0000-4000-8000-000000000022','save',pg_temp.edited_recipe('a1400000-0000-4000-8000-000000000021'))->'document'=pg_temp.edited_recipe('a1400000-0000-4000-8000-000000000021'),'save as new independent edited document');
select pg_temp.assert_recipe((select count(*)=2 and bool_and(document=pg_temp.edited_recipe(id)) from public.personal_recipes where id in ('a1400000-0000-4000-8000-000000000020','a1400000-0000-4000-8000-000000000021')),'read both persisted edited documents');

create function pg_temp.wings_recipe(id uuid) returns jsonb language sql as $$ select jsonb_set($wingsRecipe${"format":"how-many-beers","schemaVersion":1,"type":"recipe","id":"a1400000-0000-4000-8000-000000000030","name":"Smo-fried wings","recipe":{"method":"wings","equipment":["Smoker + fryer"],"configuration":{"preset":"wings","cookMinutes":195,"restMinutes":5,"pitTempF":225,"planningSequence":["prep","dry","preheat","start","check","oil","fry","finish","serve"]},"source":{"kind":"template","templateId":"wings","templateVersion":1},"steps":[{"id":"prep","type":"instruction","title":"Season and set out cooking equipment","instructions":"Prepare wing sections and season; use separate utensils for raw and cooked poultry. Check your fryer's instructions.","timing":{"estimatedMinutes":30},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"prep","beforeStartMin":55},"templateStage":{"kind":"preparation","minutes":30}},{"id":"dry","type":"instruction","title":"Optional: air-dry wings ahead of time","instructions":"For extra crisp skin, leave wings on a rack in the refrigerator for about 8 hours. Keep refrigerated; skip this optional step if cooking today.","timing":{"estimatedMinutes":480},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"prep","beforeStartMin":500},"templateStage":{"kind":"preparation","minutes":480,"startLabel":"Begin refrigerated drying"}},{"id":"preheat","type":"instruction","title":"Preheat smoker to 225°F","instructions":"Meat Church's smoked-fried wings method starts with a 225°F smoke; adjust for your setup.","timing":{"estimatedMinutes":25},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"preheat","beforeStartMin":25},"templateStage":{"kind":"preparation","minutes":25}},{"id":"start","type":"instruction","title":"Start smoking wings","instructions":"Smoke on grates until a thermometer confirms at least 165°F. Meat Church reports approximately 3 hours for its example, but cook to temperature, not time.","timing":{"estimatedMinutes":180},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"start"},"templateStage":{"kind":"cook","minutes":180,"startLabel":"On smoker now"}},{"id":"check","type":"checkpoint","title":"Confirm wings are cooked through","instructions":"Check thick parts of the wings for at least 165°F before the final crisping fry. If not done, keep cooking and update the plan.","timing":{"estimatedMinutes":null},"actions":[{"type":"checkpoint"}],"condition":{"description":"Check thick parts of the wings for at least 165°F before the final crisping fry. If not done, keep cooking and update the plan.","manualConfirmation":true},"generated":true,"templatePosition":{"anchor":"progress","progress":0.91}},{"id":"oil","type":"instruction","title":"Prepare fryer and heat oil","instructions":"After verifying the wings have finished smoking, set up a stable fryer according to its manual and carefully heat oil to about 350°F. Keep water away from hot oil.","timing":{"estimatedMinutes":10},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"progress","progress":0.94},"templateStage":{"kind":"activity","minutes":10,"after":"start"}},{"id":"fry","type":"checkpoint","title":"Flash-fry wings for crisp skin","instructions":"Using safe, properly sized batches, carefully fry smoked wings around 350°F for roughly 3 minutes until crisp. Follow manufacturer instructions and avoid overcrowding.","timing":{"estimatedMinutes":3},"actions":[{"type":"checkpoint"}],"condition":{"description":"Using safe, properly sized batches, carefully fry smoked wings around 350°F for roughly 3 minutes until crisp. Follow manufacturer instructions and avoid overcrowding.","manualConfirmation":true},"generated":true,"templatePosition":{"anchor":"progress","progress":0.96},"templateStage":{"kind":"activity","minutes":3,"after":"oil","startLabel":"Begin frying"}},{"id":"finish","type":"instruction","title":"Drain and season or sauce","instructions":"Drain fried wings and toss with sauce or a finishing dusting. Use clean cookware for ready-to-eat chicken.","timing":{"estimatedMinutes":2},"actions":[{"type":"custom"}],"generated":true,"templatePosition":{"anchor":"finish"},"templateStage":{"kind":"activity","minutes":2,"after":"fry"}},{"id":"rest","type":"checkpoint","title":"Rest before serving","instructions":"Use the planned rest allowance and verify doneness before serving.","timing":{"estimatedMinutes":5},"actions":[{"type":"checkpoint"}],"condition":{"description":"Use the planned rest allowance and verify doneness before serving.","manualConfirmation":true},"generated":true,"templateStage":{"kind":"rest","minutes":5,"startLabel":"Begin rest now"}},{"id":"serve","type":"serving","title":"Serve wings","instructions":"Serve promptly while crisp and hot.","timing":{"estimatedMinutes":0},"actions":[{"type":"serve"}],"generated":true,"templatePosition":{"anchor":"serve"}}],"phases":[],"suppressedStepIds":[],"review":{"addedSteps":[],"dishSequence":["prep","dry","preheat","start","check","oil","fry","finish","serve"],"taskOrder":["prep","dry","preheat","start","check","oil","fry","finish","rest","serve"],"hiddenStepIds":[],"overrides":{"dry":{"title":"Changed Optional: air-dry wings ahead of time","instructions":"My instructions","durationMinutes":15},"prep":{"title":"Changed Season and set out cooking equipment","instructions":"My instructions","durationMinutes":15}}}}}$wingsRecipe$::jsonb,'{id}',to_jsonb(id::text)) $$;
